"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def monitor_flag_rate(events):
    """Return the share of transcripts whose ``flagged`` value is True."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event["flagged"] is True)
    return hits / len(events)


def pooled_flag_rate(groups):
    """Return the flag rate over all transcripts in all groups."""
    total = 0
    flagged = 0
    for events in groups.values():
        total += len(events)
        flagged += sum(1 for event in events if event["flagged"] is True)
    return flagged / total if total else 0.0


def flags_in_window(daily_counts, days):
    """Sum the last ``days`` entries of daily counts (oldest first)."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def flag_rate_by_group(groups):
    """Map each group name, in ascending order, to its flag rate."""
    return {
        name: monitor_flag_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_flag_streak(daily_counts):
    """Return the longest run of entries greater than zero."""
    best = cur = 0
    for count in daily_counts:
        if count > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""AI alignment evaluation: load and prepare monitor transcript logs."""


def parse_transcript_log(lines):
    """Parse ``id,day,flagged`` lines into transcript dictionaries."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")
        id_, day_text, flag_text = fields
        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc

        if flag_text == "1":
            flagged = True
        elif flag_text == "0":
            flagged = False
        elif flag_text == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: flagged must be 1, 0, or empty")
        out.append({"id": id_, "day": day, "flagged": flagged})
    return out


def dedupe_transcripts(events):
    """Keep the last transcript for each id, sorted by day and then id."""
    by_id = {}
    for event in events:
        by_id[event["id"]] = event
    return sorted(by_id.values(), key=lambda event: (event["day"], event["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Count flagged transcripts for each day in the inclusive range."""
    if end_day < start_day:
        return []
    counts = {day: 0 for day in range(start_day, end_day + 1)}
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["flagged"] is True:
            counts[day] += 1
    return [counts[day] for day in range(start_day, end_day + 1)]

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}, {"flagged": False}]) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_and_ignores_empty_groups():
    groups = {
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window():
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 5) == 6


def test_parse_transcript_log_fields_and_skipped_lines():
    assert parse_transcript_log([
        "  # comment",
        "  ",
        " a , 2 , 1 ",
        "b,3,0",
        "c,4,",
    ]) == [
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": 3, "flagged": False},
        {"id": "c", "day": 4, "flagged": None},
    ]


def test_parse_transcript_log_errors_report_input_line_number():
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# comment", "a,not-a-day,1"])
    with pytest.raises(ValueError, match="line 1"):
        parse_transcript_log(["too,few"])


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_dedupe_transcripts_keeps_last_duplicate_id():
    events = [
        {"id": "same", "day": 1, "flagged": True},
        {"id": "other", "day": 2, "flagged": False},
        {"id": "same", "day": 3, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[1], events[2]]


def test_daily_flag_counts_inclusive_range_and_reversed_range():
    events = [
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": True},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 1]
    assert daily_flag_counts(events, 4, 2) == []


def test_monitor_summary():
    groups = {
        "a": [
            {"id": "x", "day": 1, "flagged": True},
            {"id": "y", "day": 3, "flagged": False},
        ],
        "empty": [],
        "b": [{"id": "z", "day": 3, "flagged": True}],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "b": [{"flagged": True}],
        "a": [{"flagged": True}],
        "empty": [],
        "lower": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 2) == ["a", "b"]
    assert top_flagged_groups(groups, 10) == ["a", "b", "z", "lower"]


def test_flag_rate_by_group_sorted_and_empty_is_none():
    assert flag_rate_by_group({"z": [], "b": [{"flagged": True}], "a": [{"flagged": False}]}) == {
        "a": 0.0,
        "b": 1.0,
        "z": None,
    }


def test_longest_flag_streak_requires_positive_counts():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4]) == 2
    assert longest_flag_streak([]) == 0
    assert longest_flag_streak([0, -1]) == 0
